from collections import deque, defaultdict
class Solution:
    def minMoves(self, matrix: List[str]) -> int:
        m, n = len(matrix), len(matrix[0])
        if matrix[m-1][n-1] == '#':
            return -1
        pos = defaultdict(list)
        for i in range(m):
            for j in range(n):
                if matrix[i][j].isupper():
                    pos[matrix[i][j]].append((i, j))
        dist = [[-1] * n for _ in range(m)]
        used = set()
        dq = deque([(0, 0)])
        dist[0][0] = 0
        while dq:
            i, j = dq.popleft()
            d = dist[i][j]
            if (i, j) == (m - 1, n - 1):
                return d
            c = matrix[i][j]
            if c.isupper() and c not in used:
                used.add(c)
                for x, y in pos[c]:
                    if dist[x][y] == -1:
                        dist[x][y] = d
                        dq.appendleft((x, y))
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                x, y = i + di, j + dj
                if 0 <= x < m and 0 <= y < n and matrix[x][y] != '#' and dist[x][y] == -1:
                    dist[x][y] = d + 1
                    dq.append((x, y))
        return -1

