class Solution {
public:
    int minMoves(vector<string>& matrix) {
        int m = matrix.size(), n = matrix[0].size();
        if (matrix[m-1][n-1] == '#') return -1;
        array<vector<pair<int,int>>, 26> pos;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (isupper(matrix[i][j])) pos[matrix[i][j]-'A'].push_back({i,j});
        vector<vector<int>> dist(m, vector<int>(n, -1));
        bool used[26] = {};
        deque<pair<int,int>> dq{{0,0}};
        dist[0][0] = 0;
        while (!dq.empty()) {
            auto [i, j] = dq.front(); dq.pop_front();
            int d = dist[i][j];
            if (i == m-1 && j == n-1) return d;
            char c = matrix[i][j];
            if (isupper(c) && !used[c-'A']) {
                used[c-'A'] = true;
                for (auto [x, y] : pos[c-'A'])
                    if (dist[x][y] == -1) { dist[x][y] = d; dq.push_front({x,y}); }
            }
            int dx[] = {1,-1,0,0}, dy[] = {0,0,1,-1};
            for (int t = 0; t < 4; t++) {
                int x = i + dx[t], y = j + dy[t];
                if (x >= 0 && x < m && y >= 0 && y < n && matrix[x][y] != '#' && dist[x][y] == -1) {
                    dist[x][y] = d + 1;
                    dq.push_back({x, y});
                }
            }
        }
        return -1;
    }
};

