class Solution {
    public int minMoves(String[] matrix) {
        int m = matrix.length, n = matrix[0].length();
        if (matrix[m-1].charAt(n-1) == '#') return -1;
        List<int[]>[] pos = new List[26];
        for (int i = 0; i < 26; i++) pos[i] = new ArrayList<>();
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                char c = matrix[i].charAt(j);
                if (Character.isUpperCase(c)) pos[c - 'A'].add(new int[]{i, j});
            }
        int[][] dist = new int[m][n];
        for (int[] row : dist) Arrays.fill(row, -1);
        boolean[] used = new boolean[26];
        Deque<int[]> dq = new ArrayDeque<>();
        dq.add(new int[]{0, 0}); dist[0][0] = 0;
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        while (!dq.isEmpty()) {
            int[] cur = dq.poll(); int i = cur[0], j = cur[1], d = dist[i][j];
            if (i == m-1 && j == n-1) return d;
            char c = matrix[i].charAt(j);
            if (Character.isUpperCase(c) && !used[c - 'A']) {
                used[c - 'A'] = true;
                for (int[] p : pos[c - 'A'])
                    if (dist[p[0]][p[1]] == -1) { dist[p[0]][p[1]] = d; dq.addFirst(p); }
            }
            for (int[] dir : dirs) {
                int x = i + dir[0], y = j + dir[1];
                if (x >= 0 && x < m && y >= 0 && y < n && matrix[x].charAt(y) != '#' && dist[x][y] == -1) {
                    dist[x][y] = d + 1;
                    dq.addLast(new int[]{x, y});
                }
            }
        }
        return -1;
    }
}

