var minMoves = function(matrix) {
    const m = matrix.length, n = matrix[0].length;
    if (matrix[m-1][n-1] === '#') return -1;
    const pos = Array.from({length: 26}, () => []);
    for (let i = 0; i < m; i++)
        for (let j = 0; j < n; j++) {
            const c = matrix[i][j];
            if (c >= 'A' && c <= 'Z') pos[c.charCodeAt(0) - 65].push([i, j]);
        }
    const dist = Array.from({length: m}, () => new Array(n).fill(-1));
    const used = new Array(26).fill(false);
    const dq = [[0, 0]]; dist[0][0] = 0;
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    let head = 0;
    while (head < dq.length) {
        const [i, j] = dq[head++];
        const d = dist[i][j];
        if (i === m - 1 && j === n - 1) return d;
        const c = matrix[i][j];
        if (c >= 'A' && c <= 'Z' && !used[c.charCodeAt(0) - 65]) {
            used[c.charCodeAt(0) - 65] = true;
            for (const [x, y] of pos[c.charCodeAt(0) - 65])
                if (dist[x][y] === -1) { dist[x][y] = d; dq.unshift([x, y]); }
        }
        for (const [di, dj] of dirs) {
            const x = i + di, y = j + dj;
            if (x >= 0 && x < m && y >= 0 && y < n && matrix[x][y] !== '#' && dist[x][y] === -1) {
                dist[x][y] = d + 1;
                dq.push([x, y]);
            }
        }
    }
    return -1;
};
